<main class="container"><section class="hero compact"><h1>حساب من</h1><p><?= \VazinCMS\Security::e($user['name']) ?> · <?= \VazinCMS\Security::e($user['email']) ?></p><form method="post" action="/logout"><input type="hidden" name="_csrf" value="<?= \VazinCMS\Security::e(\VazinCMS\Security::csrf()) ?>"><button>خروج امن</button></form></section>
<section><h2>سفارش‌ها</h2><?php if(!$orders): ?><p>هنوز سفارشی ثبت نشده است.</p><?php else: ?><div class="table-wrap"><table><tr><th>شماره</th><th>محصول</th><th>مبلغ</th><th>وضعیت</th></tr><?php foreach($orders as $row): ?><tr><td><?= \VazinCMS\Security::e($row['order_number']) ?></td><td><?= \VazinCMS\Security::e($row['product_name']) ?></td><td><?= \VazinCMS\Security::e($row['amount'].' '.$row['currency']) ?></td><td><?= \VazinCMS\Security::e($row['status']) ?></td></tr><?php endforeach; ?></table></div><?php endif; ?></section>
<section><h2>خدمات فعال</h2><?php if(!$services): ?><p>هنوز خدمتی به این حساب متصل نیست.</p><?php else: ?><div class="table-wrap"><table><tr><th>خدمت</th><th>وضعیت</th><th>انقضا</th></tr><?php foreach($services as $row): ?><tr><td><?= \VazinCMS\Security::e($row['name']) ?></td><td><?= \VazinCMS\Security::e($row['status']) ?></td><td><?= \VazinCMS\Security::e((string)($row['expires_at']??'—')) ?></td></tr><?php endforeach; ?></table></div><?php endif; ?></section>
<section><h2>صورتحساب‌ها</h2><?php if(!$invoices): ?><p>صورتحسابی وجود ندارد.</p><?php else: ?><div class="table-wrap"><table><tr><th>شماره</th><th>مبلغ</th><th>وضعیت</th></tr><?php foreach($invoices as $row): ?><tr><td><?= \VazinCMS\Security::e($row['invoice_number']) ?></td><td><?= \VazinCMS\Security::e($row['total'].' '.$row['currency']) ?></td><td><?= \VazinCMS\Security::e($row['status']) ?></td></tr><?php endforeach; ?></table></div><?php endif; ?></section></main>
